                  "",
                  "v = np.array([2.0, 1.0, 2.0])",
                  "x = np.array([3.0, 0.0, 3.0])",
                  "",
                  "e = v / np.linalg.norm(v)          # unit vector along v",
                  "coef = e @ x                       # signed length of x along e",
                  "proj = coef * e                    # the projection",
                  "r = x - proj                       # the residual",
                  "print(\"||v||      =\", np.linalg.norm(v))",
                  "print(\"e . x      =\", round(coef, 4))",
                  "print(\"projection =\", np.round(proj, 4))",
                  "print(\"residual   =\", np.round(r, 4))",
                  "print(\"r . e      =\", round(r @ e, 12) + 0.0)   # + 0.0 turns -0.0 into 0.0 for printing",
                  "",
                  "def cosine(a, b):",
                  "    return a @ b / (np.linalg.norm(a) * np.linalg.norm(b))",
                  "",
                  "print(\"cosine((1,0,1), (1,1,0)) =\", round(cosine(np.array([1.0, 0, 1]), np.array([1.0, 1, 0])), 4))"
